1	// AES-256-GCM secret box for BYOK (bring-your-own-key) storage.
2	// The encryption key is derived from AUTH_SECRET via scrypt, so encrypted
3	// values are only recoverable on a server that holds the same AUTH_SECRET.
4	// This is a plain server-side module (no "use server") — safe to import from
5	// server actions and the worker, never from client bundles.
6	
7	import { createCipheriv, createDecipheriv, randomBytes, scryptSync } from "node:crypto";
8	
9	/** Derive the 32-byte AES key from AUTH_SECRET. Throws if AUTH_SECRET is unset. */
10	function deriveKey(): Buffer {
11	  const secret = process.env.AUTH_SECRET;
12	  if (!secret || !secret.trim()) {
13	    throw new Error("AUTH_SECRET is not set — cannot encrypt/decrypt secrets");
14	  }
15	  return scryptSync(secret, "nxeon-byok", 32);
16	}
17	
18	/**
19	 * Encrypt a plaintext secret. Returns "iv:tag:ciphertext" (all base64).
20	 * A fresh random 12-byte IV is used per call.
21	 */
22	export function encryptSecret(plain: string): string {
23	  const iv = randomBytes(12);
24	  const cipher = createCipheriv("aes-256-gcm", deriveKey(), iv);
25	  const enc = Buffer.concat([cipher.update(plain, "utf8"), cipher.final()]);
26	  const tag = cipher.getAuthTag();
27	  return [iv.toString("base64"), tag.toString("base64"), enc.toString("base64")].join(":");
28	}
29	
30	/**
31	 * Decrypt a value produced by encryptSecret. Returns null on any problem
32	 * (missing input, malformed value, wrong key, tampered ciphertext) so callers
33	 * can safely fall back without leaking whether decryption failed vs. was absent.
34	 */
35	export function decryptSecret(enc: string | null | undefined): string | null {
36	  if (!enc) return null;
37	  try {
38	    const [ivB64, tagB64, dataB64] = enc.split(":");
39	    if (!ivB64 || !tagB64 || !dataB64) return null;
40	    const decipher = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(ivB64, "base64"));
41	    decipher.setAuthTag(Buffer.from(tagB64, "base64"));
42	    const dec = Buffer.concat([decipher.update(Buffer.from(dataB64, "base64")), decipher.final()]);
43	    return dec.toString("utf8");
44	  } catch {
45	    return null;
46	  }
47	}
48

