import { PrismaClient } from "@prisma/client";
import { createDecipheriv, scryptSync } from "node:crypto";

function deriveKey() {
  const secret = process.env.AUTH_SECRET;
  if (!secret || !secret.trim()) throw new Error("AUTH_SECRET not set");
  return scryptSync(secret, "nxeon-byok", 32);
}
function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const [ivB64, tagB64, dataB64] = enc.split(":");
    if (!ivB64 || !tagB64 || !dataB64) return null;
    const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(ivB64, "base64"));
    d.setAuthTag(Buffer.from(tagB64, "base64"));
    return Buffer.concat([d.update(Buffer.from(dataB64, "base64")), d.final()]).toString("utf8");
  } catch { return null; }
}

const prisma = new PrismaClient();
const s = await prisma.server.findUnique({ where: { id: "cmsecmdps0001hlp27ai6mr7c" } });
if (!s) { console.error("NO_ROW"); process.exit(2); }
const pw = decryptSecret(s.rootPasswordEnc);
const out = { name: s.name, hostname: s.hostname, ipAddress: s.ipAddress, sshPort: s.sshPort, hasPw: !!pw };
process.stderr.write("META " + JSON.stringify(out) + "\n");
// write password + ip to fd 3 target file passed as argv
import { writeFileSync } from "node:fs";
writeFileSync(process.argv[2], JSON.stringify({ ip: s.ipAddress, port: s.sshPort || 22, pw }), { mode: 0o600 });
await prisma.$disconnect();

import { PrismaClient } from "@prisma/client";
import { createDecipheriv, scryptSync } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";

// minimal .env loader
for (const line of readFileSync(new URL("./.env", import.meta.url), "utf8").split("\n")) {
  const m = line.match(/^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
  if (!m) continue;
  let v = m[2];
  if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
  if (!(m[1] in process.env)) process.env[m[1]] = v;
}

function deriveKey() {
  const secret = process.env.AUTH_SECRET;
  if (!secret || !secret.trim()) throw new Error("AUTH_SECRET not set");
  return scryptSync(secret, "nxeon-byok", 32);
}
function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const [ivB64, tagB64, dataB64] = enc.split(":");
    if (!ivB64 || !tagB64 || !dataB64) return null;
    const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(ivB64, "base64"));
    d.setAuthTag(Buffer.from(tagB64, "base64"));
    return Buffer.concat([d.update(Buffer.from(dataB64, "base64")), d.final()]).toString("utf8");
  } catch { return null; }
}

const prisma = new PrismaClient();
const s = await prisma.server.findUnique({ where: { id: "cmsecmdps0001hlp27ai6mr7c" } });
if (!s) { console.error("NO_ROW"); process.exit(2); }
const pw = decryptSecret(s.rootPasswordEnc);
process.stderr.write("META " + JSON.stringify({ name: s.name, hostname: s.hostname, ipAddress: s.ipAddress, sshPort: s.sshPort, hasPw: !!pw }) + "\n");
writeFileSync(process.argv[2], JSON.stringify({ ip: s.ipAddress, port: s.sshPort || 22, pw }), { mode: 0o600 });
await prisma.$disconnect();

import { Client } from "ssh2";
import { readFileSync } from "node:fs";

const creds = JSON.parse(readFileSync(process.argv[2], "utf8"));
if (creds.ip !== "51.79.226.215") {
  console.error("IP ASSERT FAILED: " + creds.ip);
  process.exit(3);
}

// Command payload read from stdin
let script = "";
process.stdin.on("data", (d) => (script += d));
process.stdin.on("end", () => {
  const conn = new Client();
  conn.on("ready", () => {
    conn.exec(script, (err, stream) => {
      if (err) { console.error("EXEC_ERR", err.message); conn.end(); process.exit(4); }
      let out = "", errout = "";
      stream.on("close", (code) => {
        process.stdout.write(out);
        if (errout) process.stderr.write("\n--STDERR--\n" + errout);
        process.stderr.write("\n--EXIT " + code + "--\n");
        conn.end();
        process.exit(code === 0 ? 0 : 10);
      });
      stream.on("data", (d) => (out += d));
      stream.stderr.on("data", (d) => (errout += d));
    });
  });
  conn.on("error", (e) => { console.error("CONN_ERR", e.message); process.exit(5); });
  conn.connect({ host: creds.ip, port: creds.port || 22, username: "root", password: creds.pw, readyTimeout: 25000 });
});

