set -e
CONF=/etc/nginx/conf.d/kaymo-revsports.conf
cp -a "$CONF" "${CONF}.bak.$(date +%Y%m%d%H%M%S)"
cat > "$CONF" <<'NGINX'
# kaymo.revsports.ca — static site (KayMo). HTTPS via Let's Encrypt.

server {
    listen 80;
    listen [::]:80;
    server_name kaymo.revsports.ca;

    # ACME HTTP-01 — kept so certbot renewals over webroot keep working.
    location /.well-known/acme-challenge/ {
        root /var/www/kaymo;
        default_type "text/plain";
        try_files $uri =404;
    }

    # Everything else redirects to HTTPS.
    location / {
        return 301 https://$host$request_uri;
    }
}

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name kaymo.revsports.ca;

    ssl_certificate     /etc/letsencrypt/live/kaymo.revsports.ca/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/kaymo.revsports.ca/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers on;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 1d;

    root /var/www/kaymo;
    index index.html;

    # Security headers
    add_header X-Content-Type-Options "nosniff" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

    # long-cache immutable static assets
    location ~* \.(?:webp|jpg|jpeg|png|css|js|woff2?|svg|ico)$ {
        add_header Cache-Control "public, max-age=2592000" always;
        add_header X-Content-Type-Options "nosniff" always;
        add_header Referrer-Policy "strict-origin-when-cross-origin" always;
        add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
        try_files $uri =404;
    }

    location / {
        try_files $uri $uri/ /index.html;
    }
}
NGINX
echo "===WROTE CONFIG==="
nginx -t 2>&1
echo "===NGINX_T_EXIT $?==="

